- (void)textViewDidChangeSelection:(UITextView *)textView{if(self.interactionHandler)self.interactionHandler(textView.selectedRange.length>0);}
- (void)scrollViewWillBeginDragging:(UIScrollView *)scroll{if(self.interactionHandler)self.interactionHandler(YES);}
- (void)scrollViewDidEndDragging:(UIScrollView *)scroll willDecelerate:(BOOL)decelerate{if(!decelerate&&self.interactionHandler)self.interactionHandler(NO);}
- (void)scrollViewDidEndDecelerating:(UIScrollView *)scroll{if(self.interactionHandler)self.interactionHandler(NO);}
