UIView *TFAICodeBlock(NSString *source,NSString *language){return [[TFAICodeCard alloc]initWithSource:source language:language];}
void TFAIUpdateCodeBlock(UIView *view,NSString *source,NSString *language){if([view isKindOfClass:TFAICodeCard.class])[(TFAICodeCard *)view updateSource:source language:language];}

void TFAICodeBlockSetInteractionHandler(UIView *view,void(^handler)(BOOL)){if([view isKindOfClass:TFAICodeCard.class])[(TFAICodeCard *)view setInteractionHandler:handler];}
